/* @author MILO-GAO(高振銘)@2020 */ package page2020.view.css3;import page2020.view.Value;public class C3border {	public static final class Attr {		public static final String border = "border";		public static final String width = "width";		public static final String style = "style";		public static final String color = "color";		public static final String image = "border-image";		public static final String radius = "border-radius";		public static final String collapse = "border-collapse";	}	public static final class Style {		public static final String dotted = "dotted";		public static final String dashed = "dashed";		public static final String solid = "solid";		public static final String doubleStyle = "double";		public static final String groove = "groove";		public static final String ridge = "ridge";		public static final String inset = "inset";		public static final String outset = "outset";		public static final String none = "none";		public static final String hidden = "hidden";		}	public Value border(String shorthand) {		return new Value().name(Attr.border).text(shorthand);	}	public Value border(String side, String shorthand) {		return new Value().name(Attr.border + "-" + side).text(shorthand);	}	public Value width(String shorthand) {		return new Value().name(Attr.border + "-" + Attr.width).text(shorthand);	}	public Value width(String side, String pixels) {		return new Value().name(Attr.border + "-" + side + "-" + Attr.width).text(pixels);	}	public Value style(String style) {		return new Value().name(Attr.border + "-" + Attr.style).text(style);	}	public Value style(String side, String style) {		return new Value().name(Attr.border + "-" + side + "-" + Attr.style).text(style);	}	public Value color(String color) {		return new Value().name(Attr.border + "-" + Attr.color).text(color);	}	public Value color(String side, String color) {		return new Value().name(Attr.border + "-" + side + "-" + Attr.color).text(color);	}	public Value image(String shorthand) {		return new Value().name(Attr.image).text(shorthand);	}	public Value radius(String pixels) {		return new Value().name(Attr.radius).text(pixels);	}	public Value collapse(boolean collapse) {		String value = collapse ? "collapse" : "separate";		return new Value().name(Attr.collapse).text(value);	}}